#include <stdio.h>
#include <string.h>

int strangePrinter(char *s) {
    int n = (int)strlen(s);
    int dp[100][100] = {{0}};
    for (int i = 0; i < n; ++i) dp[i][i] = 1;
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len <= n; ++i) {
            int j = i + len - 1;
            dp[i][j] = dp[i][j - 1] + 1;
            for (int k = i; k < j; ++k) {
                if (s[k] == s[j]) {
                    int middle = (k + 1 <= j - 1) ? dp[k + 1][j - 1] : 0;
                    int candidate = dp[i][k] + middle;
                    if (candidate < dp[i][j]) dp[i][j] = candidate;
                }
            }
        }
    }
    return dp[0][n - 1];
}

